<script setup>
import{nextTick,ref}from'vue';import TodoEditor from'../todo-source/App.vue';import CalendarView from'./CalendarView.vue';import{fromEditorSettings,toEditorSettings,validateSettings}from'./calendar-large-model.js';import{localDate}from'../todo-source/todo-model.js';
const props=defineProps({host:Object,initialSettings:Object,initialSnapshot:Object}),view=ref(),calendarSettings=ref(validateSettings(props.initialSettings));
const editorHost={...props.host,get beforeLibrarySwitch(){return props.host.beforeLibrarySwitch;},set beforeLibrarySwitch(value){props.host.beforeLibrarySwitch=value;},request:async(method,args)=>{if(method==='settings.update'){const result=validateSettings(await props.host.request(method,fromEditorSettings(args)));calendarSettings.value=result;return toEditorSettings(result);}if(method==='settings.get')return toEditorSettings(await props.host.request(method));return props.host.request(method,args);},ready:()=>props.host.ready()};
async function editorReady(editor){if(props.host.preview||new URLSearchParams(location.search).get('verify')!=='widgetjs')return;await verifySession(editor);}
async function verifySession(editor){
 const storage=await props.host.request('storage.get'),prior=storage.verification,label='日程'+props.host.instanceId.slice(0,8),background='#'+props.host.instanceId.replaceAll('-','').slice(0,6);let invalidSaveRejected=prior?.invalidSaveRejected===true,calendarActionsVerified=prior?.calendarActionsVerified===true,futureDefinitionVerified=prior?.futureDefinitionVerified===true;
 await nextTick();const api=view.value.getApi();if(!api)throw Error('原FullCalendar未挂载');
 if(!prior?.uiVerified){
  const today=localDate(Date.now()).slice(0,8)+'15';view.value.openDate(today);await nextTick();editor.draft.value.title='';const before=JSON.stringify((await props.host.request('todo.get')).todos);await editor.saveTodo();invalidSaveRejected=before===JSON.stringify((await props.host.request('todo.get')).todos)&&editor.editError.value.includes('未保存');
  editor.draft.value.title=label;editor.draft.value.recurrence='RRULE:FREQ=MONTHLY';await nextTick();window.document.getElementById('todo-form').requestSubmit();for(let n=0;n<100&&editor.saving.value;n++)await new Promise(resolve=>setTimeout(resolve,50));if(editor.saving.value||editor.editor.value.open)throw Error('日程表单未保存：'+editor.editError.value);
  await nextTick();const stored=editor.snapshot.value.todos.find(t=>t.title===label),event=api.getEventById(stored.id);if(!event)throw Error('原日历未显示已保存日程');view.value.openEvent({event});await nextTick();const editOpened=editor.editor.value.open&&editor.draft.value.id===stored.id;editor.editor.value.close();
  const futureYear=new Date().getFullYear()+1;editor.openNew(futureYear+'-01-31');editor.draft.value.title='验收未来日程';editor.draft.value.recurrence='RRULE:FREQ=MONTHLY';await editor.saveTodo();const future=editor.snapshot.value.todos.find(t=>t.title==='验收未来日程');editor.openEdit(future.id);editor.draft.value.title='已修改未来日程';await editor.saveTodo();await nextTick();api.gotoDate(futureYear+'-01-15');await nextTick();const futureEvents=api.getEvents().filter(e=>e.id===future.id),futureEdit=futureEvents.length===1&&futureEvents[0].title==='已修改未来日程';api.today();await nextTick();editor.askDelete(future.id);await editor.remove();await nextTick();api.gotoDate(futureYear+'-01-15');await nextTick();futureDefinitionVerified=futureEdit&&!api.getEvents().some(e=>e.id===future.id);api.today();await nextTick();
  const beforeTitle=api.view.title;window.document.querySelector('.fc-next-button').click();await nextTick();const moved=api.view.title!==beforeTitle,repeatVisible=api.getEvents().some(e=>e.id===stored.id);window.document.querySelector('.fc-today-button').click();await nextTick();const returned=api.view.title===beforeTitle;
  editor.openTheme();editor.themeDraft.value.background=background;editor.themeDraft.value.radius=12;editor.themeDraft.value.firstDayOfWeek=0;await editor.saveTheme();await nextTick();calendarActionsVerified=futureDefinitionVerified&&editOpened&&moved&&returned&&repeatVisible&&api.getOption('firstDay')===0;
 }
 await view.value.refresh();await nextTick();const saved=await props.host.request('settings.get'),stored=await props.host.request('todo.get'),configurationSaved=stored.todos.some(t=>t.title===label)&&saved.background===background&&saved.firstDayOfWeek===0,imagesLoaded=window.document.querySelectorAll('.fc-daygrid-day[data-date]').length===42&&api.getEvents().some(e=>e.extendedProps.category==='lunar'),gridCell=window.document.querySelector('.fc-daygrid-day'),gridBorderInfo=gridCell?{style:getComputedStyle(gridCell).borderTopStyle,width:getComputedStyle(gridCell).borderTopWidth,color:getComputedStyle(gridCell).borderTopColor,expectedColor:getComputedStyle(window.document.querySelector('.calendar-content')).color}:null,gridBordersLoaded=!!gridBorderInfo&&gridBorderInfo.style==='solid'&&parseFloat(gridBorderInfo.width)>0&&gridBorderInfo.color===gridBorderInfo.expectedColor,stylesLoaded=gridBordersLoaded&&getComputedStyle(window.document.querySelector('.fc-toolbar')).display==='flex'&&getComputedStyle(window.document.querySelector('.calendar-content')).borderRadius==='12px';
 await props.host.request('storage.set',{...storage,verification:{uiVerified:configurationSaved&&invalidSaveRejected&&calendarActionsVerified&&imagesLoaded&&stylesLoaded,configurationSaved,invalidSaveRejected,calendarActionsVerified,futureDefinitionVerified,gridBordersLoaded,gridBorderInfo,imagesLoaded,originalCalendarEngineRendered:imagesLoaded,stylesLoaded,savedLabel:label,runtimeLoads:(prior?.runtimeLoads??0)+1,todoIds:stored.todos.map(t=>t.id),todoRevision:stored.revision,publicApiPassed:view.value.publicApiPassed,publicRows:view.value.publicCount,publicError:view.value.sourceError,renderedText:window.document.querySelector('.fc-toolbar-title').textContent,origin:location.origin}});
}
</script>
<template><TodoEditor :host="editorHost" :initial-settings="toEditorSettings(calendarSettings)" :initial-snapshot="initialSnapshot" calendar-mode :calendar-ready="editorReady"><template #default="{snapshot,settings,openNew,openEdit}"><CalendarView ref="view" :host="host" :snapshot="snapshot" :settings="settings" @add="openNew" @edit="openEdit"/></template></TodoEditor></template>
